public final class HauntDiscoveryJourneyGameTests implements FabricGameTest {
 private static final java.util.concurrent.atomic.AtomicInteger DROP_LOADS=new java.util.concurrent.atomic.AtomicInteger();
 static{net.fabricmc.fabric.api.event.lifecycle.v1.ServerEntityEvents.ENTITY_LOAD.register((entity,level)->{if(entity instanceof ItemEntity)DROP_LOADS.incrementAndGet();});}

 private static ServerPlayer player(GameTestHelper h){var cookie=net.minecraft.server.network.CommonListenerCookie.createInitial(new com.mojang.authlib.GameProfile(UUID.randomUUID(),"journey-test"),false);var p=new ServerPlayer(h.getLevel().getServer(),h.getLevel(),cookie.gameProfile(),cookie.clientInformation());var c=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(c);h.getLevel().getServer().getPlayerList().placeNewPlayer(c,p,cookie);p.setGameMode(GameType.SURVIVAL);for(int i=0;i<65;i++)p.tick();p.setPos(h.absolutePos(new BlockPos(3,3,3)).getBottomCenter());var at=p.blockPosition();for(int x=-3;x<=4;x++)for(int z=-3;z<=4;z++)h.getLevel().setBlockAndUpdate(at.offset(x,-1,z),Blocks.STONE.defaultBlockState());return p;}
 private static ServerPlayer current(ServerPlayer p){return p.getServer().getPlayerList().getPlayer(p.getUUID());}
 private static void remove(ServerPlayer p){var now=current(p);if(now!=null){p.getServer().getPlayerList().remove(now);now.discard();}}
 private static BlockPos bind(GameTestHelper h,ServerPlayer p){var pos=p.blockPosition().offset(3,0,0);h.getLevel().setBlockAndUpdate(pos,CatalogBlocks.GRAVE.defaultBlockState());var grave=(GraveEntity)h.getLevel().getBlockEntity(pos);grave.placed(p);h.assertTrue(grave.name(p,p.getGameProfile().getName()),"Owner can engrave their own name");h.getLevel().setBlockAndUpdate(pos,grave.getBlockState().setValue(CatalogBlocks.GRAVE_NATURAL,true));h.assertTrue(JourneyRuntime.graveTarget(p)!=null,"Grave is bound to player");return pos;}
 private static void die(ServerPlayer p){p.invulnerableTime=0;p.hurt(p.damageSources().fellOutOfWorld(),1000);}
 @GameTest(template=EMPTY_STRUCTURE,batch="three_slices")
 public void independent_events_and_owned_effect_protection(GameTestHelper h){var p=player(h);try{
  PlayerHauntManager.setValue(p,65);h.assertTrue(HauntEventController.trigger(p,HauntEffectKind.SLOW,true),"Risk can apply native Slowness");h.assertTrue(p.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"Native risk potion applied");h.assertTrue(HauntEventController.ready(p,false)&&!HauntEventController.ready(p,true),"Benefit and risk cooldowns are independent");HauntProtection.clearNegative(p);h.assertFalse(p.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"Protection clears haunting-owned potion");
  h.assertTrue(HauntProtection.apply(p,MobEffects.WEAKNESS,100,0,true),"Owned weakness applies");p.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,300,1));HauntProtection.clearNegative(p);h.assertTrue(p.hasEffect(MobEffects.WEAKNESS)&&p.getEffect(MobEffects.WEAKNESS).getAmplifier()==1,"External potion takes ownership and survives gear cleanup");
  h.assertTrue(HauntProtection.apply(p,MobEffects.MOVEMENT_SLOWDOWN,100,0,true),"Another owned effect can be cleared on equip");p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(CatalogItems.GHOST_GARB_HELMET));p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(CatalogItems.GHOST_GARB_CHESTPLATE));p.setItemSlot(EquipmentSlot.LEGS,new ItemStack(CatalogItems.GHOST_GARB_LEGGINGS));p.setItemSlot(EquipmentSlot.FEET,new ItemStack(CatalogItems.GHOST_GARB_BOOTS));com.howierux.mortalexpansion.equipment.EquipmentRuntime.tick(p);h.assertFalse(p.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"Full set removes owned negatives on the next equipment tick");h.assertTrue(p.hasEffect(MobEffects.WEAKNESS),"External potion survives full-set equip");h.assertTrue(HauntEventController.trigger(p,HauntEffectKind.BAD_POTION,true),"Selected risk is prevented with feedback");h.assertFalse(p.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"Prevented risk has no potion side effect");h.assertTrue(HauntEventController.trigger(p,HauntEffectKind.HELPFUL_VISITATION,true),"Protection does not suppress boon benefit");h.assertTrue(p.getInventory().contains(new ItemStack(CatalogItems.SPIRIT_BOON)),"Boon item awarded");h.assertTrue(PurityOfferings.burnTicks(new ItemStack(CatalogItems.SPIRIT_BOON))==1200,"Boon burns for one minute");
 }finally{remove(p);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="three_slices")
 public void furnace_interference_and_inventory_conversion(GameTestHelper h){var p=player(h);try{
  var level=h.getLevel();var pos=p.blockPosition().east(2);level.setBlockAndUpdate(pos,CatalogBlocks.HAUNT_FURNACE.defaultBlockState());var furnace=(HauntFurnaceEntity)level.getBlockEntity(pos);furnace.setItem(0,new ItemStack(Items.RAW_IRON,2));furnace.setItem(1,new ItemStack(Items.COAL));HauntFurnaceEntity.serverTick(level,pos,level.getBlockState(pos),furnace);
  h.assertTrue(HauntEffects.finishFurnace(level,furnace),"Furnace benefit completes one real recipe");h.assertTrue(furnace.getItem(2).is(Items.IRON_INGOT)&&furnace.getItem(0).getCount()==1,"Native output and input preserved");h.assertTrue(AdditionalHauntEffects.interference(p),"Working haunt furnace can be paused");h.assertFalse(HauntEffects.finishFurnace(level,furnace),"Paused furnace cannot be forced to complete");
  p.getInventory().setItem(9,new ItemStack(Items.OAK_PLANKS,2));h.assertTrue(HauntEffects.convert(p,true),"Plank benefit converts one inventory item");h.assertTrue(p.getInventory().getItem(9).getCount()==1&&p.getInventory().contains(new ItemStack(CatalogItems.SPIRITWOOD_PLANKS)),"Conversion preserves remainder");h.assertFalse(HauntEffects.convert(p,true),"Shared chunk cooldown prevents repeat world benefit");
 }finally{remove(p);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="three_slices")
 public void discovery_radius_names_persistence_and_well_removal(GameTestHelper h){var p=player(h);try{
  var level=h.getLevel();var pos=p.blockPosition().east(4);level.setBlockAndUpdate(pos,CatalogBlocks.SPIRITWELL.defaultBlockState());SpectralDiscovery.refresh(level);var site=SpectralSite.create("spiritwell",level.dimension().location(),pos,new BoundingBox(pos),level.getSeed());h.assertTrue(SpectralSiteIndex.get(level).find(site.id())!=null,"Placed/loaded well is indexed");
  p.setPos(pos.getCenter().add(20.01,0,0));h.assertFalse(SpectralDiscovery.discover(p,site),"Outside twenty blocks remains undiscovered");p.setPos(pos.getCenter().add(20,0,0));h.assertTrue(SpectralDiscovery.discover(p,site),"Twenty-block boundary discovers well");h.assertFalse(SpectralDiscovery.discover(p,site),"Discovery is not duplicated");h.assertTrue(SpectralDiscovery.registeredDestination(p,site.id()).name().equals(site.name()),"Named destination is exposed to future travel hook");
  var saved=SpectralSiteIndex.get(level).save(new net.minecraft.nbt.CompoundTag(),level.registryAccess());h.assertTrue(SpectralSiteIndex.load(saved,level.registryAccess()).find(site.id()).name().equals(site.name()),"Site identity/name persist natively");var cemetery=SpectralSite.create("cemetery",level.dimension().location(),pos,new BoundingBox(pos),level.getSeed());h.assertTrue(cemetery.name().endsWith(" Cemetery")&&cemetery.equals(SpectralSite.create("cemetery",level.dimension().location(),pos,new BoundingBox(pos),level.getSeed())),"Horror cemetery name is stable");
  level.removeBlock(pos,false);SpectralDiscovery.refresh(level);h.assertTrue(SpectralSiteIndex.get(level).find(site.id())==null&&!SpiritwellIndex.get(level).knownPositions().contains(pos),"Removed well no longer guides tracks");
 }finally{remove(p);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="three_slices")
 public void real_death_journey_and_corpse_recover_items_once(GameTestHelper h){var original=player(h);try{
  bind(h,original);var item=new ItemStack(Items.DIAMOND,7);item.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Escrow test"));original.getInventory().setItem(9,item);var vanishing=new ItemStack(Items.DIAMOND_HELMET);vanishing.enchant(h.getLevel().registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getHolderOrThrow(net.minecraft.world.item.enchantment.Enchantments.VANISHING_CURSE),1);original.setItemSlot(EquipmentSlot.HEAD,vanishing);int loaded=DROP_LOADS.get();die(original);h.assertTrue(DROP_LOADS.get()==loaded,"Escrowed items never spawn or enter pickup callbacks");h.assertFalse(JourneyRuntime.escrow(original).toString().contains("minecraft:diamond_helmet"),"Native Vanishing items never enter escrow");h.assertTrue(JourneyRuntime.canChoose(original),"Dead bound player can select journey");h.assertTrue(!JourneyRuntime.escrow(original).getList("Pending",10).isEmpty(),"Actual vanilla death drops enter persistent escrow");h.assertTrue(JourneyRuntime.choose(original),"Journey respawns player");var p=current(original);h.assertTrue(JourneyRuntime.active(p)&&!JourneyRuntime.canChoose(p),"Journey is spectator and cannot be chosen twice");h.assertTrue(p.blockPosition().distSqr(JourneyRuntime.graveTarget(p).pos())<10,"Journey starts at the newly respawned playerâ€™s bound grave");var body=(PlayerCorpseEntity)h.getLevel().getEntity(UUID.fromString(JourneyRuntime.body(p)));h.assertTrue(body!=null,"Persistent corpse is left at death position");p.setPos(body.position());body.tick();h.assertFalse(JourneyRuntime.active(p),"Reaching corpse returns normal survival");h.assertTrue(p.getInventory().countItem(Items.DIAMOND)==7,"Held items recovered exactly once");h.assertTrue(p.getInventory().items.stream().anyMatch(s->s.is(Items.DIAMOND)&&s.getHoverName().getString().equals("Escrow test")),"Native item components survive death escrow");body.tick();h.assertTrue(p.getInventory().countItem(Items.DIAMOND)==7,"Repeated body tick cannot duplicate recovery");
 }finally{remove(original);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="three_slices")
 public void well_return_charges_personal_and_chunk_haunt_once(GameTestHelper h){var original=player(h);try{
  bind(h,original);original.getInventory().setItem(9,new ItemStack(Items.EMERALD,5));PlayerHauntManager.setValue(original,15);var well=original.blockPosition().offset(-2,0,0);h.getLevel().setBlockAndUpdate(well,CatalogBlocks.SPIRITWELL.defaultBlockState());HauntManager.setValue(h.getLevel(),well,25);die(original);h.assertTrue(JourneyRuntime.choose(original),"Begin journey");var p=current(original);h.assertTrue(JourneyRuntime.recoverAtWell(p),"Nearest indexed well has a safe landing");h.assertTrue(PlayerHauntManager.getValue(p)==25&&HauntManager.getValue(h.getLevel(),well)==35,"Well recovery costs ten personal and local haunt: player="+PlayerHauntManager.getValue(p)+" chunk="+HauntManager.getValue(h.getLevel(),well)+" nearest="+SpiritwellIndex.get(h.getLevel()).nearest(h.getLevel(),p.position())+" expected="+well);h.assertTrue(p.getInventory().countItem(Items.EMERALD)==5,"Well return recovers items");h.assertFalse(JourneyRuntime.recoverAtWell(p),"Duplicate return packet is harmless");h.assertTrue(PlayerHauntManager.getValue(p)==25,"No duplicate charge");
 }finally{remove(original);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="three_slices")
 public void dying_in_journey_uses_vanilla_spawn_and_releases_original_items(GameTestHelper h){var original=player(h);var nether=h.getLevel().getServer().getLevel(Level.NETHER);var anchor=new BlockPos(2,90,2);try{for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++)for(int dy=-1;dy<=3;dy++)nether.setBlockAndUpdate(anchor.offset(dx,dy,dz),dy==-1?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());nether.setBlockAndUpdate(anchor,Blocks.RESPAWN_ANCHOR.defaultBlockState().setValue(RespawnAnchorBlock.CHARGE,3));original.setRespawnPosition(Level.NETHER,anchor,0,false,false);
  var grave=bind(h,original);original.getInventory().setItem(9,new ItemStack(Items.GOLD_INGOT,3));die(original);h.assertTrue(JourneyRuntime.choose(original),"Begin journey");h.assertTrue(nether.getBlockState(anchor).getValue(RespawnAnchorBlock.CHARGE)==3,"Journey selection does not spend an unrelated anchor charge");var p=current(original);var body=(PlayerCorpseEntity)h.getLevel().getEntity(UUID.fromString(JourneyRuntime.body(p)));die(p);h.assertFalse(JourneyRuntime.canChoose(p),"Journey death cannot choose another grave journey");var respawn=p.getServer().getPlayerList().respawn(p,false,Entity.RemovalReason.KILLED);p.connection.player=respawn;h.assertTrue(respawn.gameMode.getGameModeForPlayer()==GameType.SURVIVAL&&JourneyRuntime.body(respawn).isEmpty(),"Failed journey becomes ordinary survival");h.assertTrue(respawn.serverLevel()==nether&&nether.getBlockState(anchor).getValue(RespawnAnchorBlock.CHARGE)==2,"Failed journey uses the vanilla Nether anchor and spends its normal charge");h.assertTrue(respawn.getInventory().countItem(Items.GOLD_INGOT)==0,"Failure does not award body inventory");h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,body.getBoundingBox().inflate(4)).stream().anyMatch(e->e.getItem().is(Items.GOLD_INGOT)&&e.getItem().getCount()==3),"Original items released at original death site");body.tick();h.assertTrue(body.isRemoved(),"Abandoned corpse cleans itself up");
 }finally{nether.removeBlock(anchor,false);remove(original);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="three_slices")
 public void ordinary_respawn_releases_pending_drops_and_checks_grave_ownership(GameTestHelper h){var original=player(h);try{
  var pos=bind(h,original);var grave=(GraveEntity)h.getLevel().getBlockEntity(pos);h.assertFalse(grave.name(original,"Overwrite"),"Engraving cannot be overwritten by another packet");original.getInventory().setItem(9,new ItemStack(Items.IRON_INGOT,4));var death=original.position();die(original);var respawn=original.getServer().getPlayerList().respawn(original,false,Entity.RemovalReason.KILLED);original.connection.player=respawn;h.assertFalse(JourneyRuntime.active(respawn),"Normal respawn does not start journey");h.assertTrue(JourneyRuntime.escrow(respawn).getList("Pending",10).isEmpty(),"Normal choice resolves pending escrow");h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,new net.minecraft.world.phys.AABB(death,death).inflate(4)).stream().anyMatch(e->e.getItem().is(Items.IRON_INGOT)&&e.getItem().getCount()==4),"Normal choice restores native drops at death site");
 }finally{remove(original);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="three_slices")
 public void operator_commands_and_deferred_ghosts_use_real_dispatch(GameTestHelper h) throws Exception {var p=player(h);try{
  var dispatcher=p.getServer().getCommands().getDispatcher();var source=p.createCommandSourceStack().withPermission(2);h.assertTrue(dispatcher.execute("mortalexpansion haunt @s helpful_visitation",source)==1,"Operator command selects concrete benefit");h.assertTrue(p.getInventory().countItem(CatalogItems.SPIRIT_BOON)==1,"Command actually awards boon");p.getInventory().setItem(9,new ItemStack(Items.APPLE,2));p.getInventory().setItem(10,new ItemStack(Items.BONE,3));var hotbar=p.getInventory().getItem(0).copy();h.assertTrue(dispatcher.execute("mortalexpansion haunt @s shuffle",source)==1,"Specific command bypasses tier/cooldown for testing");h.assertTrue(p.getInventory().getItem(9).is(Items.BONE)&&p.getInventory().getItem(10).is(Items.APPLE)&&ItemStack.isSameItemSameComponents(hotbar,p.getInventory().getItem(0)),"Shuffle preserves stacks/components and leaves hotbar alone");
  p.setPos(p.position().add(0,400,0));var data=HauntEventData.get(h.getLevel());long before=data.pendingGhosts(),cooldown=HauntProtection.state(p).getLong("CooldownUntil");h.assertTrue(HauntEventController.trigger(p,HauntEffectKind.GHOST,true),"Ghost selection queues when no usable well is nearby");h.assertTrue(data.pendingGhosts()==before+1&&HauntProtection.state(p).getLong("CooldownUntil")==cooldown,"Held encounter does not start a new delivery cooldown");var saved=data.save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess());h.assertTrue(HauntEventData.load(saved,h.getLevel().registryAccess()).pendingGhosts()==before+1,"Pending selection survives native save/load");data.deliveredGhost();
 }finally{remove(p);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="three_slices")
 public void keep_inventory_journey_never_duplicates_or_escrows_carried_items(GameTestHelper h){var original=player(h);boolean previous=h.getLevel().getGameRules().getBoolean(GameRules.RULE_KEEPINVENTORY);try{
  h.getLevel().getGameRules().getRule(GameRules.RULE_KEEPINVENTORY).set(true,h.getLevel().getServer());bind(h,original);original.getInventory().setItem(9,new ItemStack(Items.DIAMOND,8));die(original);h.assertTrue(JourneyRuntime.escrow(original).getList("Pending",10).isEmpty(),"keepInventory creates no fake death drops");h.assertTrue(JourneyRuntime.choose(original),"Journey still available with keepInventory");var p=current(original);h.assertTrue(p.getInventory().countItem(Items.DIAMOND)==8,"Native inventory is retained across respawn");var body=(PlayerCorpseEntity)h.getLevel().getEntity(UUID.fromString(JourneyRuntime.body(p)));p.setPos(body.position());body.tick();h.assertTrue(p.getInventory().countItem(Items.DIAMOND)==8&&JourneyRuntime.escrow(p).getList("Held",10).isEmpty(),"Body recovery cannot duplicate retained items");
 }finally{h.getLevel().getGameRules().getRule(GameRules.RULE_KEEPINVENTORY).set(previous,h.getLevel().getServer());remove(original);}h.succeed();}
}
